import re
from datetime import date
from decimal import Decimal

_QTY = re.compile(r"[0-9]+")
_PRICE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _check(fields):
    if len(fields) != 4:
        return None, f"expected 4 fields, got {len(fields)}"
    name, qty, price, day = fields
    if not name:
        return None, "name is empty"
    if not _QTY.fullmatch(qty) or int(qty) < 1:
        return None, "qty must be a positive integer"
    if not _PRICE.fullmatch(price):
        return None, "price must be a non-negative amount with at most 2 decimals"
    parsed = None
    if _DATE.fullmatch(day):
        try:
            parsed = date.fromisoformat(day)
        except ValueError:
            pass
    if parsed is None:
        return None, "date is not a valid ISO date"
    return {"name": name, "qty": int(qty), "price": Decimal(price), "date": parsed}, None


def validate(rows):
    valid, errors = [], []
    seen = {}
    for row in rows:
        number = row["line"]
        item, error = _check(row["fields"])
        if item is not None:
            key = (item["name"].casefold(), item["date"])
            if key in seen:
                item, error = None, f"duplicate of line {seen[key]}"
            else:
                seen[key] = number
        if error:
            errors.append({"line": number, "error": error})
        else:
            valid.append({"line": number, **item})
    return valid, errors
