from decimal import Decimal


def summarize(valid, errors):
    total = sum((r["price"] * r["qty"] for r in valid), Decimal(0))
    out = [
        f"rows: {len(valid)} valid, {len(errors)} invalid",
        f"total: {total:.2f}",
    ]
    out += [f"line {e['line']}: {e['error']}" for e in errors]
    latest = max((r["date"] for r in valid), default=None)
    out.append(f"latest: {latest.isoformat() if latest else '-'}")
    return out
